  var c=Fixture();var result=RouterAudit.Analyze(c);check("IPsec rules never authorize ordinary Internet transit without matching policy",result.Findings.Where(f=>f.Key.StartsWith("forward:")).All(f=>f.Status=="Закрыто"));
