  c=Fixture();c.Tables["raw4"]=[R(".id=*6","chain=prerouting","action=notrack")];check("Notrack cannot bypass unconditional downstream input drop",RouterAudit.Analyze(c).Findings.Where(f=>f.Key.StartsWith("dns:")).All(f=>f.Status=="Закрыто"));
  c=Fixture();c.Tables["nat4"]=[R(".id=*A","chain=dstnat","action=dst-nat","dst-address=198.51.100.3","protocol=udp","dst-port=5353","to-addresses=10.23.0.8","to-ports=53")];result=RouterAudit.Analyze(c);check("UDP DNAT tracks original and translated DNS ports",result.Findings.Any(f=>f.Key.StartsWith("nat:udp:")&&f.Key.EndsWith(":53")&&f.Status=="Разрешено firewall: любые источники"));
  c.Tables["filter4"].Insert(0,R(".id=*7","chain=forward","action=drop","protocol=udp","dst-port=53"));check("Translated UDP port is checked in forward",RouterAudit.Analyze(c).Findings.Where(f=>f.Key.StartsWith("nat:")).All(f=>f.Status=="Закрыто"));
  c=Fixture();c.Tables["filter4"].Insert(0,R(".id=*8","chain=input","action=accept","src-address=203.0.113.9"));result=RouterAudit.Analyze(c);check("Address restricted accept stays restricted in complete rule path",result.Findings.Where(f=>f.Key.StartsWith("dns:")).All(f=>f.Status=="Разрешено firewall: ограниченные источники"));
  c=Fixture();c.Tables["filter4"].Insert(0,R(".id=*9","chain=forward","action=accept","protocol=tcp","dst-port=45680-45690"));result=RouterAudit.Analyze(c);check("Custom firewall port ranges contribute boundaries beyond standard service catalog",result.Findings.Any(f=>f.Key=="forward:32:uplink:45680"&&f.Status=="Разрешено firewall: любые источники"));
