  var network=new NetworkStore(Path.Combine(folder,"topic-delivery"));network.State(s=>{s.Notifications.Add(new(){EntityKey="router-audit:1:fixture",Severity=Severity.Critical});return true;},true);int sends=0;await NetworkNotifications.FlushAsync(network,t,default,(_,_)=>{sends++;return Task.CompletedTask;});check("Telegram category filter applies at actual delivery boundary",sends==0&&network.State(s=>s.Notifications.All(n=>n.HandledAt!=null)));
  var journals=new AgentEventStore(Path.Combine(folder,"green-journal"));var green=new NetworkStore(Path.Combine(folder,"green-journal"));
  var problemId="fixture-closed";var journalPath=Path.Combine(folder,"green-journal","agent-events-1.json");Directory.CreateDirectory(Path.GetDirectoryName(journalPath)!);File.WriteAllText(journalPath,JsonSerializer.Serialize(new AgentEventState{Problems=[new(){Id=problemId,RuleId="reboot",Open=false,Title="Restored",Severity=Severity.Critical,Resolution="stable"}]},AgentWire.Json));
  green.State(s=>{s.Notifications.Add(new(){EntityKey="journal:1:"+problemId,Severity=Severity.Critical,Topic="journal.reboot",HandledAt=DateTime.UtcNow,Result="Отправлено"});return true;},true);journals.Flush(1,green);journals.Flush(1,green);check("Resolved journal queues green restoration once only after a delivered opening",green.State(s=>s.Notifications.Count(n=>n.EntityKey=="journal:1:"+problemId+":recovery"&&n.Transition.StartsWith("ЗАКРЫТО"))==1));
