 static async Task Certificates(string folder,Action<string,bool> check,Func<Action,bool> reject){
  // Ordinary network fixtures must survive startup without automatic rotation.
  var stableRoot=Path.Combine(folder,"stable-cert");Directory.CreateDirectory(stableRoot);
  using(var stableKey=RSA.Create(2048)){
   var stableRequest=new CertificateRequest("CN=stable-fixture",stableKey,HashAlgorithmName.SHA256,RSASignaturePadding.Pkcs1);
   using var stable=stableRequest.CreateSelfSigned(DateTimeOffset.UtcNow.AddMinutes(-2),DateTimeOffset.UtcNow.AddDays(180));
   File.WriteAllBytes(Path.Combine(stableRoot,"server.pfx"),stable.Export(X509ContentType.Pfx,"fixture"));
   var stablePin=stable.GetCertHashString(HashAlgorithmName.SHA256);var stableStore=new AgentStore(stableRoot,stablePin,s=>s,s=>s);
   using var stableManager=new CertificateLifecycle(stableRoot,"fixture","127.0.0.1",stableStore);stableManager.Maintain(DateTime.UtcNow);
   check("Startup preserves pinned certificate outside renewal window",stableManager.Status().Fingerprint==stablePin&&string.IsNullOrEmpty(stableManager.Status().NextFingerprint)&&stableManager.Status().PendingTelegram==0);
  }
  var root=Path.Combine(folder,"auto-cert");Directory.CreateDirectory(root);const string password="fixture";var now=DateTime.UtcNow;using var rsa=RSA.Create(2048);var request=new CertificateRequest("CN=fixture",rsa,HashAlgorithmName.SHA256,RSASignaturePadding.Pkcs1);using var old=request.CreateSelfSigned(DateTimeOffset.UtcNow.AddDays(-1),DateTimeOffset.UtcNow.AddDays(20));File.WriteAllBytes(Path.Combine(root,"server.pfx"),old.Export(X509ContentType.Pfx,password));var pin=old.GetCertHashString(HashAlgorithmName.SHA256);var store=new AgentStore(root,pin,s=>s,s=>s);var anchor=store.AuthorityCertificate();var initial=store.Trust();
  using var manager=new CertificateLifecycle(root,password,"127.0.0.1",store);check("HTTPS renewal stages before expiry and signs next fingerprint",manager.Maintain(now)&&manager.Status().NextFingerprint.Length==64&&AgentTrust.Verify(store.Trust(),anchor).Pins.Contains(manager.Status().NextFingerprint));
  check("HTTPS preparation is idempotent",!manager.Maintain(now.AddHours(1)));check("HTTPS activates automatically without restart or confirmation",manager.Maintain(now.AddDays(8))&&manager.Status().Fingerprint!=pin&&manager.Status().PendingTelegram==1);
  check("Offline agent trusts new leaf through old authority",ServerTrust.Accept(manager.Current,"127.0.0.1",new[]{pin},anchor));check("Anchored server trust verifies IP SAN",!ServerTrust.Accept(manager.Current,"127.0.0.2",new[]{pin},anchor));check("Anchored trust never accepts expired HTTPS leaf",!ServerTrust.IssuedBy(manager.Current,anchor,"127.0.0.1",now.AddYears(2)));check("Unknown replacement is rejected",!ServerTrust.Accept(old,"127.0.0.1",[],anchor));
  var info=manager.Trust("https://127.0.0.1:7443/");var learned=ClientServerTrust.Learn(info,info.ServerUrl,pin,pin,null);check("Client retains authenticated authority across automatic renewal",ClientServerTrust.Learn(info,info.ServerUrl,pin,info.Fingerprint,learned).ObservedPin==info.Fingerprint);check("Client rejects signed trust rollback",reject(()=>ClientServerTrust.Learn(info with{Trust=initial},info.ServerUrl,pin,info.Fingerprint,learned)));
  await manager.SendAsync(new(),info.ServerUrl,"UTC",default,(_,_)=>Task.CompletedTask);check("Certificate notice survives disabled Telegram",manager.Status().PendingTelegram==1);bool failed=false;try{await manager.SendAsync(new(){Enabled=true},info.ServerUrl,"UTC",default,(_,_)=>throw new IOException());}catch(IOException){failed=true;}check("Certificate notice survives send failure",failed&&manager.Status().PendingTelegram==1);
  int sends=0;string sent="";await manager.SendAsync(new(){Enabled=true,Info=false},info.ServerUrl,"Russian Standard Time",default,(message,_)=>{sends++;sent=message;return Task.CompletedTask;});await manager.SendAsync(new(){Enabled=true},info.ServerUrl,"UTC",default,(_,_)=>{sends++;return Task.CompletedTask;});check("Certificate notice includes full fingerprint and sends once outside topic filters",sends==1&&sent.Contains(info.Fingerprint)&&sent.Contains("перевыпущен"));
  using(var again=new CertificateLifecycle(root,password,"127.0.0.1",store))check("Renewed certificate and notice cursor persist after restart",again.Status().Fingerprint==info.Fingerprint&&again.Status().PendingTelegram==0);
  using var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(10));var port=((IPEndPoint)listener.LocalEndpoint).Port;var server=Task.Run(async()=>{using var socket=await listener.AcceptTcpClientAsync(timeout.Token);using var tls=new SslStream(socket.GetStream());await tls.AuthenticateAsServerAsync(new SslServerAuthenticationOptions{ServerCertificate=manager.Current,EnabledSslProtocols=SslProtocols.Tls12},timeout.Token);await tls.WriteAsync(new byte[]{42},timeout.Token);});using var client=new TcpClient();await client.ConnectAsync(IPAddress.Loopback,port,timeout.Token);using var stream=new SslStream(client.GetStream(),false,(_,cert,_,_)=>ServerTrust.Accept(cert,"127.0.0.1",new[]{pin},anchor));await stream.AuthenticateAsClientAsync(new SslClientAuthenticationOptions{TargetHost="127.0.0.1",EnabledSslProtocols=SslProtocols.Tls12},timeout.Token);var b=new byte[1];var count=await stream.ReadAsync(b,timeout.Token);await server;check("Actual TLS handshake succeeds after server certificate rotation",count==1&&b[0]==42);
  var statePath=Path.Combine(root,"certificate-lifecycle.json");var state=JsonSerializer.Deserialize<CertificateLifecycleState>(File.ReadAllText(statePath))!;state.Current=pin;state.Next=info.Fingerprint;state.Notices=[];File.WriteAllText(statePath,JsonSerializer.Serialize(state));using(var recovered=new CertificateLifecycle(root,password,"127.0.0.1",store))check("Interrupted certificate file switch recovers durable notice",recovered.Status().PendingTelegram==1);
 }
 static async Task Times(string folder,Action<string,bool> check){var original=AppTime.ZoneId;try{
  var utc=new DateTime(2026,10,20,19,44,0,DateTimeKind.Utc);var wall=new DateTime(2026,10,20,22,44,0);AppTime.Configure("Russian Standard Time");check("Server timezone maps Moscow independently of machine timezone",AppTime.FromUtc(utc)==wall&&AppTime.ToUtc(wall)==utc);check("IMAP explicit offset uses selected server timezone",AppTime.FromOffset(new DateTimeOffset(wall,TimeSpan.FromHours(3)))==wall);
  AppTime.Configure("UTC");check("Report with offset converted while naive report uses server wall time",ReportAnalyzer.ParseDate("2026-10-20T22:44:00+03:00")==utc&&ReportAnalyzer.ParseDate("20.10.2026 22:44:00")==wall);
  using(AppTime.Scope("Russian Standard Time")){AppTime.Configure("UTC");await Task.Yield();check("In-flight monitor retains timezone while settings change",AppTime.FromUtc(utc)==wall);}check("Scoped clock restores global zone",AppTime.ZoneId=="UTC");
  var f=new DatabaseFactory(new(){SqlitePath=Path.Combine(folder,"utc-migration.db")});await f.InitializeAsync();await using(var db=f.Create()){db.Reports.Add(new(){Provider="test",ReceivedAt=wall,OccurredAt=wall});db.Payments.Add(new(){Title="calendar",DueDate=wall.Date});await db.SaveChangesAsync();await db.Database.ExecuteSqlRawAsync("UPDATE sa2_ReportEvent SET ReceivedAt='2026-10-20 22:44:00',OccurredAt='2026-10-20 22:44:00'");await using var tx=await db.Database.BeginTransactionAsync();await TimeStorage.EnsureAsync(db,AppTime.Resolve("Russian Standard Time"));await tx.CommitAsync();}
  await using(var db=f.Create())check("Legacy event migrated once from old Windows timezone to UTC",(await db.Reports.SingleAsync()).ReceivedAt==utc);
  AppTime.Configure("Russian Standard Time");await using(var db=f.Create()){check("Stored UTC event displays in newly selected zone",(await db.Reports.SingleAsync()).ReceivedAt==wall);check("Calendar payment date unaffected by timezone change",(await db.Payments.SingleAsync()).DueDate==wall.Date);await using var tx=await db.Database.BeginTransactionAsync();await TimeStorage.EnsureAsync(db,TimeZoneInfo.Utc);await tx.CommitAsync();}AppTime.Configure("UTC");await using(var db=f.Create())check("Repeated startup never shifts old timestamps a second time",(await db.Reports.SingleAsync()).ReceivedAt==utc);
  AppTime.Configure("Russian Standard Time");var encoded=MailUpdates.Serialize([new(){Key="test",FirstReceived=wall,LastReceived=wall}]);check("Embedded mail history stores UTC and renders server zone",encoded.Contains("2026-10-20T19:44:00Z")&&MailUpdates.Parse(encoded).Single().LastReceived==wall);
 }finally{AppTime.Configure(original);}}
}
